import unittest
from calc import evaluate, ExpressionError


class TestCalc(unittest.TestCase):
    def test_single_integer(self):
        self.assertEqual(evaluate("123"), 123.0)

    def test_addition_multiplication(self):
        self.assertEqual(evaluate("2+3*4"), 14.0)

    def test_parentheses_and_negation(self):
        self.assertEqual(evaluate("(1+2.5)*-3"), -10.5)

    def test_division(self):
