    def test_unary_minus(self):
        self.assertEqual(evaluate("-5+10"), 5.0)

    def test_division_by_zero(self):
        with self.assertRaisesRegex(ExpressionError, "Division by zero"):
            evaluate("10/0")

    def test_empty_expression(self):
        with self.assertRaisesRegex(ExpressionError, "Empty expression"):
            evaluate("")

    def test_trailing_characters(self):
        with self.assertRaisesRegex(ExpressionError, "Unexpected character: a"):
            evaluate("2+3abc")

    def test_unbalanced_parentheses(self):
        with self.assertRaisesRegex(ExpressionError, "Unbalanced parentheses"):
            evaluate("(1+2")


